insert into public.noam_ramzi_hints (exercise_id,hint_1,hint_2,hint_3,status,source,source_id,source_exercise_text,review_note) values
('G7-T01-A-Q01א','מה משמעות סימן שלילי בטבלת מלאי, ואיזה מדף מייצג את החוסר העמוק ביותר ביחס לתכנון?','בדקו את הערכים השליליים בטבלה וקבעו איזה מהם נמצא במרחק הגדול ביותר מנקודת האפס בכיוון השלילי.','זהו את המדף שבו כמות הארגזים החסרים היא הגדולה מכולם, ורשמו את שמו בליווי הסבר.','verified','zero-spoiler-v2.1','G7-T01-A-Q01א','במחסן מציינים הפרש מן המלאי המתוכנן. הטבלה מציגה את ההפרש בארגזים; סימן חיובי מציין עודף: מדף אורן (-11), מדף תמר (-2), מדף ליבנה (+5), מדף דקל (+8). איזה מדף דורש את התוספת הגדולה ביותר כדי להגיע לתכנון? הסבירו.','נבדק מול הסעיף המודפס בדף העבודה; הרמזים מתאימים בדיוק לסעיף זה וללא חשיפת פתרון.'),
('G7-T01-A-Q01ב','כיצד מרחק הערך מנקודת האפס מודד קרבה לתכנון, ללא תלות בסימן החיובי או השלילי?','השוו את המרחקים מנקודת האפס של כל המדפים לקביעת הקרבה לתכנון, ולאחר מכן בדקו בנפרד את הערכים החיוביים בלבד.','קבעו איזה מדף מציג את המרחק הקטן ביותר מאפס עבור השאלה הראשונה, ובדקו איזה מדף מציג את הערך החיובי הגדול מכולם עבור השאלה הבאה.','verified','zero-spoiler-v2.1','G7-T01-A-Q01ב','באיזה מדף המלאי קרוב ביותר לתכנון? האם זה גם המדף שבו העודף הגדול ביותר?','נבדק מול הסעיף המודפס בדף העבודה; הרמזים מתאימים בדיוק לסעיף זה וללא חשיפת פתרון.'),
('G7-T01-A-Q04א','לאילו כיוונים שונים על גבי הציר ניתן להתקדם מנקודת האפס באותו מרחק נתון?','מדדו את המרחק הנתון פעם אחת לכיוון ימין של האפס ופעם נוספת לכיוון שמאל של האפס.','רשמו את המספרים המכוונים המתאימים לנקודות שמצאתם בכל צד של הציר.','verified','zero-spoiler-v2.1','G7-T01-C-Q01א','נתון כי המרחק של מספר מסוים מנקודת האפס הוא 6 יחידות. אילו מספרים יכולים להתאים לתיאור זה?','הרמזים נכתבו לתרגיל אחר מזה שמופה (G7-T01-E-Q01א), והועברו לסעיף זה באותו נושא. נבדק מול הסעיף המודפס: הרמזים מתאימים לו, נכונים ואינם מגלים את התשובה. שני בודקים לא מצאו סיבה לפסול.'),
('G7-T01-A-Q34א','כיצד מעבר לצורת רישום אחידה של מספר עם נקודה מסייע בהשוואת מיקומים על גבי הציר?','המירו תחילה את השבר לצורה עם נקודה, ומקמו בדמיונכם את שני הערכים ביחס לנקודת האפס.','קבעו מי מהמספרים נמצא ימינה יותר על גבי הציר (או האם הם מתלכדים באותה נקודה), ובחרו את סימן ההשוואה המתאים.','verified','zero-spoiler-v2.1','G7-T01-B-Q01א','השוו בין המספרים והציבו סימן מתאים: $-1/2 ___ -0.8$','הרמזים נכתבו לתרגיל אחר מזה שמופה (G7-T01-B-Q01א), והועברו לסעיף זה באותו נושא. נבדק מול הסעיף המודפס: הרמזים מתאימים לו, נכונים ואינם מגלים את התשובה. שני בודקים לא מצאו סיבה לפסול.'),
('G7-T01-B-Q01א','כאשר נקודת ייחוס נקבעת בגובה אפס, איזה סימן מתמטי מייצג מיקום הנמצא מתחתיה?','קשרו בין תנועה או מיקום מתחת לנקודת האפס לבין הסימן המתאים לצד השלילי של הציר.','כתבו את הגובה הנתון בליווי הסימן המתאים למיקום שמתחת לקו הייחוס, בצירוף יחידות המידה.','verified','zero-spoiler-v2.1','G7-T01-B-Q01א','בתחנת מחקר נקבע רציף הסירה כגובה אפס. הדיווחים הם במטרים. מכשיר נמצא 8 מטרים מתחת לרציף. רשמו את גובהו המכוון.','נבדק מול הסעיף המודפס בדף העבודה; הרמזים מתאימים בדיוק לסעיף זה וללא חשיפת פתרון.'),
('G7-T01-E-Q01א','כיצד משלבים מרחק נתון מנקודת האפס יחד עם סימן מוגדר כדי לשחזר את ערכו המלא של המספר?','התאימו לכל אות את הסימן הנתון יחד עם מרחקה מנקודת האפס, ולאחר מכן השוו בין ערך שלילי לערך חיובי.','רשמו את שני הערכים המשוחזרים, והציבו ביניהם יחס סדר מתאים לפי מקומם על ציר המספרים.','verified','zero-spoiler-v2.1','G7-T01-C-Q01א','ארבע קריאות חיישן מופיעות בטבלה. היצרן מפרסם רק את המרחק שלהן מן האפס: A מרחקו 2.6, B מרחקו 0.9, C מרחקו 4.1, D מרחקו 0. נתון ש־A שלילי ו־B חיובי. שחזרו את שניהם וסדרו ביניהם.','נבדק מול הסעיף המודפס בדף העבודה; הרמזים מתאימים בדיוק לסעיף זה וללא חשיפת פתרון.'),
('G7-T02-A-Q01א','כיצד מכפילים את כמות השנתות בגודל של שנתה בודדת, ואיזה סימן מעניק הצד שביחס לנקודת האפס?','כפלו עבור כל צבע את כמות הצעדים בגודל השנתה הנתון, והוסיפו סימן בהתאם לצד של הציר שבו היא ממוקמת.','צמצמו את השברים או המירו לשבר מעורב, ורשמו את התוצאה הסופית עבור כל נקודה.','verified','zero-spoiler-v2.1','G7-T02-A-Q01א','על ישר מספרים המרחק בין כל שתי שנתות סמוכות הוא 1/4. בטבלה מתואר המקום של שלוש נקודות לפי מספר השנתות שלהן מהאפס: ירוקה: 9 שנתות בצד השלילי; כחולה: 6 שנתות בצד החיובי; אדומה: 2 שנתות בצד השלילי. איזה מספר מתאים לכל נקודה?','נבדק מול הסעיף המודפס בדף העבודה; הרמזים מתאימים בדיוק לסעיף זה וללא חשיפת פתרון.'),
('G7-T02-A-Q01ב','כיצד קובעים מי הנקודה הרחוקה ביותר מנקודת האפס לפי כמות השנתות הכוללת, ללא תלות בכיוון?','זהו את מספר השנתות הגדול ביותר בטבלה, וחשבו את ההפרש בינו לבין מספר השנתות של הנקודה הכחולה.','כפלו את הפרש השנתות בגודל שנתה בודדת, ורשמו את המרחק העודף ביחידות על גבי הציר.','verified','zero-spoiler-v2.1','G7-T02-A-Q01ב','איזו נקודה רחוקה ביותר מהאפס? בכמה היא רחוקה ממנו יותר מהנקודה הכחולה?','נבדק מול הסעיף המודפס בדף העבודה; הרמזים מתאימים בדיוק לסעיף זה וללא חשיפת פתרון.'),
('G7-T02-B-Q01א','כיצד מבטאים תנועה שמאלה על ציר המספרים כפעולת חיבור עם מספר בעל סימן מתאים?','רשמו תרגיל חיבור שבו לנקודת ההתחלה מתווסף שיעור התזוזה עם סימן המייצג את כיוון התנועה.','חשבו את סכום המספרים בעלי הסימנים השונים וקבעו את נקודת העצירה המדויקת.','verified','zero-spoiler-v2.1','G7-T02-B-Q01א','על ישר המספרים, תנועה לכיוון החיובי היא הוספה של מספר חיובי, ותנועה לכיוון השלילי היא הוספה של מספר שלילי. כתבו תרגיל חיבור ומצאו היכן עוצרים כאשר יוצאים מ־2 וזזים 8 צעדים לכיוון השלילי.','נבדק מול הסעיף המודפס בדף העבודה; הרמזים מתאימים בדיוק לסעיף זה וללא חשיפת פתרון.'),
('G7-T02-B-Q03ב','כאשר מוסיפים מספר שלילי על גבי ציר המספרים, לאיזה כיוון נעים מנקודת ההתחלה?','התחילו בנקודה הראשונה על גבי הציר, ובצעו צעדים בכיוון המתאים למספר הנוסף.','בדקו לאיזו נקודה מספרית הגעתם על גבי הציר בסיום התנועה, ורשמו אותה.','verified','zero-spoiler-v2.1','G7-T02-A-Q01א','חשבו: $(-4) + (-3)$','הרמזים נכתבו לתרגיל אחר מזה שמופה (G7-T02-A-Q01א), והועברו לסעיף זה באותו נושא. נבדק מול הסעיף המודפס: הרמזים מתאימים לו, נכונים ואינם מגלים את התשובה. שני בודקים לא מצאו סיבה לפסול.'),
('G7-T02-B-Q15א','כיצד ניתן להמיר פעולת חיסור לפעולת חיבור עם המספר הנגדי?','כתבו את תרגיל החיסור כתרגיל חיבור של המספר הנגדי, ומקמו את התנועה על גבי הציר.','קבעו את המרחק והכיוון הסופי ביחס לנקודת האפס כדי לרשום את התוצאה.','verified','zero-spoiler-v2.1','G7-T02-A-Q01ב','חשבו: $(+5) - (+8)$','הרמזים נכתבו לתרגיל אחר מזה שמופה (G7-T02-A-Q01ב), והועברו לסעיף זה באותו נושא. נבדק מול הסעיף המודפס: הרמזים מתאימים לו, נכונים ואינם מגלים את התשובה. שני בודקים לא מצאו סיבה לפסול.'),
('G7-T02-B-Q15ה','איזה שינוי מתרחש בפעולת החשבון כאשר מחסרים מספר בעל סימן שלילי?','המירו את חיסור המספר השלילי לחיבור של המספר הנגדי לו, וקבעו את כיוון התנועה על הציר.','בצעו את פעולת החיבור המתקבלת לקביעת הערך המספרי הסופי.','verified','zero-spoiler-v2.1','G7-T02-B-Q01א','חשבו: $(-12) - (-7)$','הרמזים נכתבו לתרגיל אחר מזה שמופה (G7-T02-B-Q01א), והועברו לסעיף זה באותו נושא. נבדק מול הסעיף המודפס: הרמזים מתאימים לו, נכונים ואינם מגלים את התשובה. שני בודקים לא מצאו סיבה לפסול.'),
('G7-T02-E-Q01א','כיצד ממירים תזוזה של שנתות לערך מספרי עם סימן לפי כיוון התנועה, ואיך מאחדים את כל השלבים לביטוי כולל?','כפלו כל תנועה בגודל השנתה היסודי, הצמידו סימן לפי הכיוון, וכנסו את כל השברים בעלי המכנה המשותף לתרגיל בודד.','חברו את המונים בהתחשב בסימנים המכוונים, צמצמו את השבר שהתקבל, וקבעו את נקודת הסיום.','verified','zero-spoiler-v2.1','G7-T02-C-Q01א','על ישר מספרים המרחק בין כל שתי שנתות סמוכות הוא 1/3. נקודה יוצאת מ־2/3, זזה 8 שנתות לכיוון השלילי, ואחר כך 3 שנתות לכיוון החיובי. כתבו כל תזוזה כמספר עם סימן, כתבו תרגיל אחד לכל התנועה, ומצאו היכן עצרה הנקודה.','נבדק מול הסעיף המודפס בדף העבודה; הרמזים מתאימים בדיוק לסעיף זה וללא חשיפת פתרון.'),
('G7-T02-E-Q17א','כיצד קיבוץ מספרים לפי סימניהם מסייע בפישוט תרגיל שרשרת?','המירו את כל פעולות החיסור לחיבור של מספרים נגדיים, וקבצו בנפרד את הערכים החיוביים ואת הערכים השליליים.','חשבו את תוצאת החיבור בין הסכום שקיבלתם מכל קבוצה לקבלת התוצאה הסופית.','verified','zero-spoiler-v2.1','G7-T02-C-Q01א','חשבו: $-15 + 8 - (-10) - 12$','הרמזים נכתבו לתרגיל אחר מזה שמופה (G7-T02-E-Q01א), והועברו לסעיף זה באותו נושא. נבדק מול הסעיף המודפס: הרמזים מתאימים לו, נכונים ואינם מגלים את התשובה. שני בודקים לא מצאו סיבה לפסול.'),
('G7-T03-A-Q01א','מהו כלל הסימנים עבור מכפלה שבה כל הגורמים חולקים את אותו הסימן?','קבעו תחילה את סימן התוצאה לפי כללי הכפל במספרים מכוונים, ולאחר מכן כפלו את הערכים המספריים ללא סימן.','בצעו את פעולת הכפל בין המספרים ורשמו את התוצאה בליווי הסימן שנקבע.','verified','zero-spoiler-v2.1','G7-T03-A-Q01א','חשבו את המכפלה. החליטו קודם מה הסימן של התוצאה, ואז חשבו את הגודל: (-1.4) * (-5)','נבדק מול הסעיף המודפס בדף העבודה; הרמזים מתאימים בדיוק לסעיף זה וללא חשיפת פתרון.'),
('G7-T03-A-Q01ב','איזה סימן מתקבל במכפלה כאשר לגורמים יש סימנים מנוגדים?','קבעו את הסימן הסופי, צמצמו את המכנה של השבר עם המספר השלם, וכפלו במונה.','השלימו את פעולת הכפל ורשמו את המספר שהתקבל יחד עם הסימן המתאים.','verified','zero-spoiler-v2.1','G7-T03-A-Q01ב','חשבו את המכפלה: (-3/5) * 30','נבדק מול הסעיף המודפס בדף העבודה; הרמזים מתאימים בדיוק לסעיף זה וללא חשיפת פתרון.'),
('G7-T03-B-Q01א','כאשר כופלים גורם חיובי בגורם שלילי, מה יהיה סימן המכפלה?','קבעו תחילה את סימן התוצאה בהתאם לכלל הסימנים השונים, ולאחר מכן כפלו את שני הגדלים המספריים.','רשמו את התוצאה המספרית לצד הסימן שקבעתם בשלב הראשון.','verified','zero-spoiler-v2.1','G7-T03-B-Q01א','בכל מכפלה פועלים באותו סדר: קודם סימן, אחר כך גודל, ורק אז כותבים את התוצאה. חשבו: 13 * (-2)','נבדק מול הסעיף המודפס בדף העבודה; הרמזים מתאימים בדיוק לסעיף זה וללא חשיפת פתרון.'),
('G7-T03-B-Q01ב','כיצד נקבע סימן המכפלה כאשר כופלים מספרים בעלי סימנים זהים?','היזכרו בקשר הסימנים בעת כפל של גורמים בעלי אותו הסימן, וכפלו את ערכי המספרים.','רשמו את המכפלה בצירוף הסימן המתמטי המתאים לפי הכלל.','verified','zero-spoiler-v2.1','G7-T03-A-Q01ב','חשבו: $(-7) × (-4)$','הרמזים נכתבו לתרגיל אחר מזה שמופה (G7-T03-A-Q01ב), והועברו לסעיף זה באותו נושא. נבדק מול הסעיף המודפס: הרמזים מתאימים לו, נכונים ואינם מגלים את התשובה. שני בודקים לא מצאו סיבה לפסול.'),
